/// <reference lib="webworker" />
import { precacheAndRoute, cleanupOutdatedCaches } from "workbox-precaching";

declare const self: ServiceWorkerGlobalScope;

// Cleanup old caches from previous versions
cleanupOutdatedCaches();

// Precache all assets listed in the manifest generated by Vite PWA plugin
precacheAndRoute(self.__WB_MANIFEST);

self.addEventListener("install", () => {
  // Do NOT call skipWaiting() here — let the user decide via the update prompt.
  // The new service worker stays in "waiting" state until SKIP_WAITING is posted.
  console.log("[SW] New service worker installed, waiting for user activation.");
});

// Listen for explicit activation from PwaUpdatePrompt ("Update Now" button)
self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") {
    console.log("[SW] SKIP_WAITING received — activating new service worker.");
    self.skipWaiting();
  }
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

// Implement robust SPA navigation fallback when offline
self.addEventListener("fetch", (event) => {
  if (event.request.mode === "navigate") {
    event.respondWith(
      fetch(event.request).catch(async () => {
        // Serve precached index.html so the Single Page Application loads seamlessly offline
        const cachedApp =
          (await caches.match("/index.html")) ||
          (await caches.match("index.html")) ||
          (await caches.match("/FairTab/index.html"));
        if (cachedApp) {
          return cachedApp;
        }

        const cachedFallback =
          (await caches.match("/FairTab/offline.html")) ||
          (await caches.match("offline.html")) ||
          (await caches.match("/offline.html"));
        return (
          cachedFallback ||
          new Response("FairTab Offline", {
            status: 200,
            headers: { "Content-Type": "text/html" },
          })
        );
      })
    );
  }
});

// Web Push event listener
self.addEventListener("push", (event) => {
  if (!event.data) return;

  try {
    const payload = event.data.json();
    const title = payload.title || "FairTab Notification";
    const options = {
      body: payload.body || "New update in FairTab",
      icon: payload.icon || "/icons/icon-192.png",
      badge: payload.badge || "/icons/icon-192.png",
      tag: payload.tag || "fairtab-alert",
      data: payload.data || { url: "/" },
      vibrate: payload.vibrate || [200, 100, 200, 100, 200],
    } as NotificationOptions;

    event.waitUntil(self.registration.showNotification(title, options));
  } catch (err) {
    console.error("Error processing push payload:", err);
    // Plain text fallback
    const text = event.data.text();
    event.waitUntil(
      self.registration.showNotification("FairTab", {
        body: text,
        icon: "/icons/icon-192.png",
      })
    );
  }
});

// Notification click and deep-link routing
self.addEventListener("notificationclick", (event) => {
  event.notification.close();

  const baseUrl = self.location.origin;
  const rawUrl = event.notification.data?.url;
  let targetUrl = `${baseUrl}/#/overview`;

  if (rawUrl) {
    if (rawUrl.startsWith("http://") || rawUrl.startsWith("https://")) {
      // If legacy GitHub pages URL is embedded in an old notification payload, rewrite to live domain
      if (rawUrl.includes("rohitpvt.github.io")) {
        const hashIdx = rawUrl.indexOf("#");
        const hashPart = hashIdx !== -1 ? rawUrl.substring(hashIdx) : "#/overview";
        targetUrl = `${baseUrl}/${hashPart}`;
      } else {
        targetUrl = rawUrl;
      }
    } else if (rawUrl.startsWith("#")) {
      targetUrl = `${baseUrl}/${rawUrl}`;
    } else if (rawUrl.startsWith("/")) {
      targetUrl = `${baseUrl}${rawUrl}`;
    }
  }

  event.waitUntil(
    (async () => {
      // Match all window clients including uncontrolled ones under this origin/scope
      const clientList = await self.clients.matchAll({
        type: "window",
        includeUncontrolled: true,
      });

      // 1. If an existing tab/window is open, focus it and bring it forward immediately
      for (const client of clientList) {
        if ("focus" in client) {
          try {
            const focusedClient = await (client as WindowClient).focus();
            if (targetUrl && "navigate" in focusedClient && focusedClient.url !== targetUrl) {
              await focusedClient.navigate(targetUrl);
            }
            return focusedClient;
          } catch (err) {
            console.warn("[SW] Focus failed on client, trying next:", err);
          }
        }
      }

      // 2. Otherwise, open a new window and bring it to the foreground
      if (self.clients.openWindow) {
        return await self.clients.openWindow(targetUrl);
      }
    })()
  );
});
